import{_ as d,l as r,o as a,c as s,v as o,p as n,x as c,d as i,i as l,S as A}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"条件码与谓词执行","description":"","frontmatter":{"title":"条件码与谓词执行","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/condition-codes-predication.md","filePath":"cs/condition-codes-predication.md","lastUpdated":1789023840000}'),h={name:"cs/condition-codes-predication.md"};function p(C,e,E,S,m,R){const t=r("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="条件码与谓词执行" tabindex="-1">条件码与谓词执行 <a class="header-anchor" href="#条件码与谓词执行" aria-label="Permalink to &quot;条件码与谓词执行&quot;">​</a></h1><div class="epigraph"><p>比较的结果可以藏进 NZCV / EFLAGS，也可以写成 GPR 里的 0/1；谓词把短分支收成选路，避免前端为一条 `if` 付冲刷。</p><footer>—— 据 ARM Architecture Reference Manual；Intel SDM；The RISC-V Instruction Set Manual；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/bit-manip-ext">上一课</a>的 <code>min</code>/<code>clz</code> 写出的是寄存器值。<a href="/cs/aarch64-isa">AArch64</a> 已点名 NZCV，<a href="/cs/arm-vs-riscv">ARM 对 RISC-V</a> 把「条件码 vs 比较进寄存器」留到本课。缺口是 <strong>标志位与谓词</strong>：谁写、谁读、如何消掉短分支。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>x86：多数整数运算更新 EFLAGS（ZF/SF/OF/CF）；<code>jcc</code> 与 <code>cmov</code> 读它们。ARM：可选 <code>S</code> 后缀写 NZCV，<code>b.cond</code> / <code>csel</code> 消费。RISC-V：无条件码，<code>blt</code> 直接比较两个 GPR，<code>slt</code> 把布尔写进寄存器。缺口不是再介绍分支指令，而是<strong>隐式标志堆 vs 显式比较</strong>对流水线与编译器的后果。</p><p>谓词：用布尔选结果而不跳转。部分谓词是 <code>cmov</code>/<code>csel</code>；A32 曾给多数指令条件域；Itanium 把谓词寄存器做成常规。 <a href="/cs/rvv-vector">RVV</a> 的掩码是向量谓词，本课对照标量。</p><h3 id="谓词不是「取消分支预测」" tabindex="-1">谓词不是「取消分支预测」 <a class="header-anchor" href="#谓词不是「取消分支预测」" aria-label="Permalink to &quot;谓词不是「取消分支预测」&quot;">​</a></h3><p>长偏置分支仍该跳。谓词消灭的是<strong>短、难预测</strong>的 <code>if</code>，并可能拉长数据依赖、多执行两边。把 NZCV 当预测器状态，下一课 <a href="/cs/gshare-predictor">gshare</a> 会对不上：预测器看的是分支历史，不是条件码 CSR。</p><p><span class="marginnote">ARM ARM 的 PSTATE 与 CSEL。Intel SDM 的 Jcc/CMOV 与 EFLAGS。RISC-V 无标志是刻意选择。CA:AQA 讨论谓词与条件移动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器：若 ISA 有 <code>csel</code> 且两边都便宜，发条件选；否则发比较+分支，把方向交给前端。RISC-V 用 <code>slt</code>+掩码或分支；B 扩展的 <code>min</code> 是谓词的代数特例。x86 部分标志改写曾造成 stall，微结构用合并与重命名缓解——那是后课乱序，本课只要求「标志是额外的写口」。</p>',11)),(a(),n(A,null,{default:c(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CMP%5B%22%E6%AF%94%E8%BE%83%22%5D%20--%3E%20CC%5B%22%E5%86%99%20NZCV%20%2F%20EFLAGS%22%5D%0A%20%20CMP%20--%3E%20GPR%5B%22slt%20%E5%86%99%20GPR%22%5D%0A%20%20CC%20--%3E%20BR%5B%22%E6%9D%A1%E4%BB%B6%E5%88%86%E6%94%AF%22%5D%0A%20%20CC%20--%3E%20SEL%5B%22csel%20%2F%20cmov%22%5D%0A%20%20GPR%20--%3E%20BR%0A%20%20SEL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%A4%9A%E5%AD%97%E8%8A%82%E5%9C%A8%E5%86%85%E5%AD%98%E9%87%8C%E7%9A%84%E6%AC%A1%E5%BA%8F%22%5D%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与 <a href="/cs/fence-instructions">fence</a>：条件码是核内控制状态，不参与多核内存序。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ISA 对照到这里，控制流接口已经分叉：ARM/x86 的隐式 CC 让一条 <code>sub</code> 同时服务算术与后续 <code>b.eq</code>；RISC-V 把布尔留在 GPR，译码与重命名少一个标志堆。下一课大小端处理的是<strong>数据在内存中的字节序</strong>，与「比较结果放哪」正交，但 ABI 会同时规定两者。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Itanium 编译器全集，不把 GPU 的 divergence 当标量谓词。不列全部 <code>jcc</code> 助记符。不进入数据库 SQL 谓词下推。</p><p>后课默认：x86/ARM 用条件码；RISC-V 比较进寄存器或直接分支；<code>cmov</code>/<code>csel</code> 是部分谓词。下一课大小端。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条件码是隐式布尔；RISC-V 选择显式 GPR。</li><li>谓词用选路换短分支，不取消预测器。</li><li>向量掩码已在 RVV，本课钉标量。</li><li>出处：ARM ARM；Intel SDM；RISC-V ISA；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const f=d(h,[["render",p]]);export{_ as __pageData,f as default};
